CREATE TABLE public.creator_games (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 80), description text NOT NULL CHECK (length(trim(description)) BETWEEN 1 AND 2000), category text NOT NULL CHECK (category IN ('sports','racing','arcade','puzzle','adventure','strategy')), price_cents integer NOT NULL DEFAULT 0 CHECK (price_cents >= 0 AND price_cents <= 100000), currency text NOT NULL DEFAULT 'usd' CHECK (currency = 'usd'), status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.creator_games TO authenticated;
GRANT ALL ON public.creator_games TO service_role;
ALTER TABLE public.creator_games ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Browse approved or own games" ON public.creator_games FOR SELECT TO authenticated USING (status = 'approved' OR creator_id = auth.uid() OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator'));
CREATE POLICY "Create own game drafts" ON public.creator_games FOR INSERT TO authenticated WITH CHECK (creator_id = auth.uid() AND status IN ('draft','pending') AND NOT public.is_suspended(auth.uid()));
CREATE POLICY "Edit own games" ON public.creator_games FOR UPDATE TO authenticated USING (creator_id = auth.uid() AND NOT public.is_suspended(auth.uid())) WITH CHECK (creator_id = auth.uid() AND status IN ('draft','pending'));
CREATE POLICY "Delete own games" ON public.creator_games FOR DELETE TO authenticated USING (creator_id = auth.uid());
CREATE TABLE public.creator_game_builds (game_id uuid PRIMARY KEY REFERENCES public.creator_games(id) ON DELETE CASCADE, creator_id uuid NOT NULL DEFAULT auth.uid(), launch_url text NOT NULL CHECK (length(launch_url) <= 2000 AND launch_url ~ '^https://[a-zA-Z0-9][a-zA-Z0-9.-]+\.[a-zA-Z]{2,}(:443)?(/|$)' AND launch_url !~* '^https://(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.)'));
GRANT SELECT, INSERT, UPDATE ON public.creator_game_builds TO authenticated;
GRANT ALL ON public.creator_game_builds TO service_role;
ALTER TABLE public.creator_game_builds ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners and reviewers read game builds" ON public.creator_game_builds FOR SELECT TO authenticated USING (creator_id = auth.uid() OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator'));
CREATE POLICY "Owners create game builds" ON public.creator_game_builds FOR INSERT TO authenticated WITH CHECK (creator_id = auth.uid() AND EXISTS (SELECT 1 FROM public.creator_games g WHERE g.id = game_id AND g.creator_id = auth.uid() AND g.status IN ('draft','pending')));
CREATE POLICY "Owners edit draft game builds" ON public.creator_game_builds FOR UPDATE TO authenticated USING (creator_id = auth.uid()) WITH CHECK (creator_id = auth.uid() AND EXISTS (SELECT 1 FROM public.creator_games g WHERE g.id = game_id AND g.creator_id = auth.uid() AND g.status IN ('draft','pending')));
CREATE TABLE public.creator_game_sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), game_id uuid NOT NULL REFERENCES public.creator_games(id), creator_id uuid NOT NULL, buyer_id uuid NOT NULL, amount_cents integer NOT NULL CHECK (amount_cents >= 0), platform_fee_cents integer NOT NULL CHECK (platform_fee_cents >= 0 AND platform_fee_cents <= amount_cents), refunded_cents integer NOT NULL DEFAULT 0 CHECK (refunded_cents BETWEEN 0 AND amount_cents), creator_net_cents integer NOT NULL CHECK (creator_net_cents BETWEEN 0 AND amount_cents), currency text NOT NULL DEFAULT 'usd' CHECK (currency = 'usd'), environment text NOT NULL CHECK (environment IN ('sandbox','live')), payment_reference text NOT NULL UNIQUE, payout_status text NOT NULL DEFAULT 'not_scheduled' CHECK (payout_status IN ('not_scheduled','scheduled','paid','failed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.creator_game_sales TO authenticated;
GRANT ALL ON public.creator_game_sales TO service_role;
ALTER TABLE public.creator_game_sales ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own game financial records" ON public.creator_game_sales FOR SELECT TO authenticated USING (creator_id = auth.uid() OR buyer_id = auth.uid());
CREATE FUNCTION public.protect_creator_game_review() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.creator_id <> OLD.creator_id THEN RAISE EXCEPTION 'Creator cannot change'; END IF; IF current_user IN ('authenticated','anon') AND NEW.status IN ('approved','rejected') THEN RAISE EXCEPTION 'Review required'; END IF; IF (NEW.title,NEW.description,NEW.category,NEW.price_cents) IS DISTINCT FROM (OLD.title,OLD.description,OLD.category,OLD.price_cents) THEN NEW.status := 'pending'; END IF; NEW.updated_at := now(); RETURN NEW; END $$;
CREATE TRIGGER protect_game_review BEFORE UPDATE ON public.creator_games FOR EACH ROW EXECUTE FUNCTION public.protect_creator_game_review();
CREATE FUNCTION public.review_creator_game(_game_id uuid, _approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator')) THEN RAISE EXCEPTION 'Reviewer access required'; END IF; IF _approve AND NOT EXISTS (SELECT 1 FROM public.creator_game_builds WHERE game_id = _game_id) THEN RAISE EXCEPTION 'Game URL required'; END IF; UPDATE public.creator_games SET status = CASE WHEN _approve THEN 'approved' ELSE 'rejected' END WHERE id = _game_id AND status IN ('pending','approved'); IF NOT FOUND THEN RAISE EXCEPTION 'Game not awaiting review'; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_creator_game(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_creator_game(uuid,boolean) TO authenticated;
CREATE FUNCTION public.launch_creator_game(_game_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE g public.creator_games; result text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO g FROM public.creator_games WHERE id = _game_id; IF NOT FOUND THEN RAISE EXCEPTION 'Game not found'; END IF; IF g.creator_id <> auth.uid() AND NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator')) THEN IF g.status <> 'approved' THEN RAISE EXCEPTION 'Game unavailable'; END IF; IF g.price_cents > 0 THEN RAISE EXCEPTION 'Paid game sales are not available yet'; END IF; END IF; SELECT launch_url INTO result FROM public.creator_game_builds WHERE game_id = _game_id; IF result IS NULL THEN RAISE EXCEPTION 'Game URL missing'; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.launch_creator_game(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.launch_creator_game(uuid) TO authenticated;
COMMENT ON TABLE public.creator_game_sales IS 'Service-written financial ledger reserved for verified game payments; checkout remains disabled until protected delivery, refund reconciliation, fees and payout readiness are approved.';